import pandas as pd
import numpy as np
from sklearn.metrics import accuracy_score

train = pd.read_csv('data/spr_bench_train.csv')
feature_cols = [c for c in train.columns if c.startswith('token_')]

# Let's reconsider the SOTA of 70%.
# What if the SOTA is 70% because the labels are generated by a rule, but 30% of the labels are randomly flipped?
# If 30% of the labels are randomly flipped, then the true rule should have ~70% accuracy on the training set.
# But we haven't found ANY rule with ~70% accuracy.
# This means the true rule is NOT any of the simple rules we've checked.
# What if the rule is based on the *number of unique tokens*?

best_acc = 0
best_rule = ""

def check_rule(preds, name):
    global best_acc, best_rule
    acc = accuracy_score(train['label'], preds)
    if acc < 0.5:
        acc = 1 - acc
        name = f"NOT ({name})"
    if acc > best_acc:
        best_acc = acc
        best_rule = name
    if abs(acc - 0.7) < 0.05:
        print(f"Rule: {name}, Acc: {acc:.4f}")

# 61. Number of unique tokens > threshold
for i in range(1, 9):
    preds = train[feature_cols].apply(lambda x: len(set(x)) > i, axis=1)
    check_rule(preds, f"unique tokens > {i}")

# 62. Number of unique shapes > threshold
for i in range(1, 5):
    preds = train[feature_cols].apply(lambda x: len(set(t[0] for t in x)) > i, axis=1)
    check_rule(preds, f"unique shapes > {i}")

# 63. Number of unique colors > threshold
for i in range(1, 5):
    preds = train[feature_cols].apply(lambda x: len(set(t[1] for t in x)) > i, axis=1)
    check_rule(preds, f"unique colors > {i}")

# 64. Contains a token that appears exactly N times
for i in range(1, 9):
    preds = train[feature_cols].apply(lambda x: any(list(x).count(t) == i for t in set(x)), axis=1)
    check_rule(preds, f"contains token appearing exactly {i} times")

print(f"\nBest rule: {best_rule} with accuracy {best_acc:.4f}")
